def git(*args, input_text=None, check=True):
    return subprocess.run(
        ["git", *args], input=input_text, text=True,
        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, check=check
    )

def main():
    try:
        git("rev-parse", "--show-toplevel")
        branch = git("branch", "--show-current").stdout.strip()
    except (subprocess.CalledProcessError, FileNotFoundError) as exc:
        raise SystemExit("Run this script from inside the target Git repository.") from exc
    if branch != EXPECTED_BRANCH:
        raise SystemExit(
            f"Expected branch {EXPECTED_BRANCH!r}, got {branch!r}. "
            "Switch to the release branch before applying; no files changed."
        )
    patch = zlib.decompress(base64.b64decode("".join(PATCH_B64))).decode()
    check = git("apply", "--check", "--binary", "-", input_text=patch, check=False)
    if check.returncode:
        raise SystemExit(
            "Patch does not apply cleanly; no files changed. Resolve branch drift first.\n"
            + check.stdout
        )
    git("apply", "--binary", "-", input_text=patch)
    print("Applied Asteria 0.5.0 release-cleanup patch.")
    print("Review with: git status --short && git diff --check")
    print("Then run: gradle test")

if __name__ == "__main__":
    main()
